7	/**
8	 * Extracts content from either a file path or data URI
9	 */
10	function getCertificateContent(input: string): string {
11	  if (input.startsWith("data:")) {
12	    // Parse data URI: data:[<mediatype>][;base64],<data>
13	    const [header, data] = input.split(",");
14	    if (header.includes("base64")) {
15	      return Buffer.from(data, "base64").toString("utf8");
16	    } else {
17	      return decodeURIComponent(data);
18	    }
19	  } else {
20	    // Assume it's a file path
21	    return fs.readFileSync(input, "utf8");
22	  }
23	}
