import * as fs from "node:fs";
import tls from "node:tls";

/**
 * Extracts content from either a file path or data URI
 */
export function getCertificateContent(input: string): string {
  if (input.startsWith("data:")) {
    // Parse data URI: data:[<mediatype>][;base64],<data>
    const commaIndex = input.indexOf(",");
    const header = input.slice(0, commaIndex);
    const data = input.slice(commaIndex + 1);
    if (header.includes("base64")) {
      return Buffer.from(data, "base64").toString("utf8");
    } else {
      return decodeURIComponent(data);
    }
  } else {
    // Assume it's a file path
    return fs.readFileSync(input, "utf8");
  }
}

/**
 * Singleton cache for SSL certificates.
 *
 * The set of "fixed" certificates (system root certificates plus anything
 * referenced by NODE_EXTRA_CA_CERTS) is computed lazily on first access and
 * reused for the lifetime of the process. Custom certificates (referenced via
 * request options) are cached by their path/data URI so they only need to be
 * read/decoded once.
 */
export class CertsCache {
  private static _instance: CertsCache | undefined;

  private _fixedCa: string[] = [];
  private _initialized: boolean = false;
  private _customCerts: Map<string, string> = new Map();

  static getInstance(): CertsCache {
    if (!CertsCache._instance) {
      CertsCache._instance = new CertsCache();
    }
    return CertsCache._instance;
  }

  get fixedCa(): string[] {
    if (!this._initialized) {
      const globalCerts: string[] = [];
      if (process.env.NODE_EXTRA_CA_CERTS) {
        globalCerts.push(getCertificateContent(process.env.NODE_EXTRA_CA_CERTS));
      }
      if (process.env.IS_BINARY) {
        if (Array.isArray(globalAgent.options.ca)) {
          globalCerts.push(
            ...globalAgent.options.ca.map((cert) => cert.toString()),
          );
        } else if (typeof globalAgent.options.ca !== "undefined") {
          globalCerts.push(globalAgent.options.ca.toString());
        }
      }

      this._fixedCa = Array.from(
        new Set([...tls.rootCertificates, ...globalCerts]),
      );
      this._initialized = true;
    }
    return this._fixedCa;
  }

  getCachedCustomCert(path: string): string {
    const cached = this._customCerts.get(path);
    if (cached !== undefined) {
      return cached;
    }
    const content = getCertificateContent(path);
    this._customCerts.set(path, content);
    return content;
  }

  getAllCachedCustomCerts(caBundlePath: string[] | string): string[] {
    const paths =
      typeof caBundlePath === "string" ? [caBundlePath] : caBundlePath;
    return paths.map((path) => this.getCachedCustomCert(path));
  }

  getCa(caBundlePath: undefined | string | string[]): string[] {
    if (caBundlePath) {
      return [...this.fixedCa, ...this.getAllCachedCustomCerts(caBundlePath)];
    }
    return this.fixedCa;
  }

  clear(): void {
    this._customCerts.clear();
    this._initialized = false;
    this._fixedCa = [];
  }
}
