21	/**
22	 * Checks whether a NO_PROXY-style pattern matches a hostname, taking an
23	 * optional port into account.
24	 * @param pattern The NO_PROXY pattern (may include a port, e.g. "example.com:8080")
25	 * @param hostname The hostname to check (may include a port)
26	 * @returns True if the pattern matches the hostname
27	 */
28	export function patternMatchesHostname(
29	  pattern: string,
30	  hostname: string,
31	): boolean {
32	  const [patternHost, patternPort] = pattern.toLowerCase().split(":");
33	  const [host, port] = hostname.toLowerCase().split(":");
34	
35	  // Port matching: if the pattern specifies a port, the hostname must match it
36	  if (patternPort && patternPort !== port) {
37	    return false;
38	  }
39	
40	  // Exact match
41	  if (patternHost === host) return true;
42	
43	  // Wildcard domain match (*.example.com)
44	  if (patternHost.startsWith("*.") && host.endsWith(patternHost.substring(1)))
45	    return true;
46	
47	  // Domain suffix match (.example.com)
48	  if (patternHost.startsWith(".") && host.endsWith(patternHost.slice(1)))
49	    return true;
50	
51	  return false;
52	}
