54	/**
55	 * Checks if a hostname should bypass proxy based on the NO_PROXY environment
56	 * variable and request options.
57	 * @param hostname The hostname to check
58	 * @param requestOptions Optional request options that may specify additional
59	 *   noProxy patterns
60	 * @returns True if the hostname should bypass proxy
61	 */
62	export function shouldBypassProxy(
63	  hostname: string,
64	  requestOptions: RequestOptions | undefined,
65	): boolean {
66	  const noProxy = process.env.NO_PROXY || process.env.no_proxy;
67	
68	  const patterns: string[] = [];
69	  if (noProxy) {
70	    patterns.push(...noProxy.split(",").map((item) => item.trim()));
71	  }
72	  if (requestOptions?.noProxy) {
73	    patterns.push(...requestOptions.noProxy);
74	  }
75	
76	  if (patterns.length === 0) return false;
77	
78	  return patterns.some((pattern) => patternMatchesHostname(pattern, hostname));
79	}
